import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Markbox","description":"","frontmatter":{},"headers":[],"relativePath":"components/markbox.md","filePath":"components/markbox.md"}'),i={name:"components/markbox.md"};function n(s,e,d,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="markbox" tabindex="-1">Markbox <a class="header-anchor" href="#markbox" aria-label="Permalink to &quot;Markbox&quot;">​</a></h1><p>Markbox is the place of an icon: a square that centres a mark, so that the first column of a list stays in place.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it at the start of list items whose marks differ in size: icons, color marks, a <a href="./swatch">Swatch</a> or an emoji (<code>glyph</code>). The font of an emoji comes from <code>--kata-glyph-font</code>, set by the container.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>glyph</code></td><td><code>false</code></td><td>The content is an emoji</td></tr><tr><td><code>children</code></td><td>required</td><td>The mark</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A square of <code>--kata-height-icon</code> with no surface and no line, its content centred. It does not change the height of a list item. An emoji is not trimmed.</p><p>A Markbox is a seat: its baseline is that of a trimmed line centred in it. Beside text that may wrap, it goes in a <a href="./row">Row</a> with <code>align=&quot;first&quot;</code>, and the mark is centred on the ink of the text&#39;s first line (<a href="./../measuring#a-mark-beside-text">a mark beside text</a>).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/markbox/" title="Markbox" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/markbox/" target="_blank" rel="noopener">Markbox</a></figcaption></figure>',11)])])}const f=a(i,[["render",n]]);export{p as __pageData,f as default};
